(window.__docs=window.__docs||{})["01-2025-tt-nhnn"]={"id":"01-2025-tt-nhnn","nhom":"giay-phep","nhom_con":null,"loai":"Thông tư","so_hieu":"01/2025/TT-NHNN","ngay":null,"tieu_de":"Quy định về cấp Giấy phép lần đầu, cấp đổi Giấy phép của quỹ tín dụng nhân dân","can_cu":[["p","<i>Căn cứ Luật Ngân hàng Nhà nước Việt Nam ngày 16 tháng 6 năm 2010;</i>",""],["p","<i>Căn cứ Luật Các tổ chức tín dụng ngày 18 tháng 01 năm 2024;</i>",""],["p","<i>Căn cứ Luật Hợp tác xã ngày 20 tháng 6 năm 2023; </i>",""],["p","<i>Căn cứ Nghị định số 2 6 /202 5 /NĐ-CP ngày 2 4 tháng 0 2 năm 202 5 của Chính phủ quy định chức năng, nhiệm vụ, quyền hạn và cơ cấu tổ chức của Ngân hàng Nhà nước Việt Nam;</i>",""],["p","<i>Căn cứ Nghị định số 162 /202 4 /NĐ-CP ngày 20 tháng 1 2 năm 202 4 của Chính phủ quy định điều kiện cấp Giấy phép đối với quỹ tín dụng nhân dân, tổ chức tài chính vi mô và điều kiện đối với chủ sở hữu của tổ chức tín dụng là công ty trách nhiệm hữu hạn một thành viên, cổ đông sáng lập, thành viên sáng lập;</i>",""],["p","<i>Theo đề nghị của Cục trưởng Cục An toàn hệ thống các tổ chức tín dụng;</i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam ban hành Thông tư quy định về cấp Giấy phép lần đầu, cấp đổi Giấy phép của quỹ tín dụng nhân dân.</i>",""]],"lich_su":[],"dong_thoi_gian":[],"chuong":[{"id":"c1","title":"Chương I — QUY ĐỊNH CHUNG","articles":[{"id":"dieu-1","so":"1","ten":"Phạm vi điều chỉnh","nd":[["p","Thông tư này quy định <b>về :</b>",""],["p","<b>1. Hồ sơ, trình tự cấp Giấy phép lần đầu của quỹ tín dụng nhân dân</b>.","k"],["p","<b>2. Nguyên tắc, hồ sơ, trình tự cấp đổi Giấy phép của quỹ tín dụng nhân dân</b>.","k"],["p","3. Thẩm quyền cấp Giấy phép lần đầu, cấp đổi Giấy phép, cấp bản sao Giấy phép từ sổ gốc.","k"],["p","4. Giấy phép, trình tự cấp bản sao Giấy phép từ sổ gốc.","k"],["p","5. Nộp lệ phí cấp <b>Giấy phép lần đầu, cấp đổi Giấy phép.</b>","k"],["p","<b>6 . Khai trương hoạt động.</b>",""],["p","7. Việc thông báo thông tin về <b>cấp Giấy phép lần đầu, cấp đổi Giấy phép của quỹ tín dụng nhân dân cho cơ quan đăng ký kinh doanh .</b>","k"]]},{"id":"dieu-2","so":"2","ten":"Đối tượng áp dụng","nd":[["p","1. Quỹ tín dụng nhân dân.","k"],["p","2. Tổ chức, cá nhân có liên quan đến việc cấp Giấy phép lần đầu<b>, cấp đổi Giấy phép</b> của quỹ tín dụng nhân dân, cấp bản sao Giấy phép từ sổ gốc.","k"]]},{"id":"dieu-3","so":"3","ten":"Giải thích từ ngữ","nd":[["p","Trong Thông tư này, các từ ngữ dưới đây được hiểu như sau:",""],["p","1. <i><i>Ban trù bị</i></i> là một nhóm người do thành viên sáng lập lựa chọn thay mặt các thành viên sáng lập triển khai các công việc liên quan đến việc đề nghị cấp Giấy phép. Ban trù bị phải có tối thiểu 03 thành viên, trong đó có 01 thành viên là Trưởng ban.","k"],["p","2. Ngân hàng Nhà nước Khu vực là Ngân hàng Nhà nước chi nhánh tại các Khu vực nơi quỹ tín dụng nhân dân đặt trụ sở chính.","k"],["p","3. Hội nghị thành lập là Hội nghị của các thành viên sáng lập quỹ tín dụng nhân dân, có nhiệm vụ:","k"],["p","a) Thông qua dự thảo Điều lệ quỹ tín dụng nhân dân; Đề án thành lập quỹ tín dụng nhân dân; Danh sách nhân sự dự kiến bầu, bổ nhiệm làm Chủ tịch và các thành viên khác của Hội đồng quản trị, Trưởng ban và các thành viên khác của Ban kiểm soát, Giám đốc của quỹ tín dụng nhân dân nhiệm kỳ đầu tiên;","d"],["p","b) Bầu Ban trù bị, Trưởng ban trù bị từ những thành viên sáng lập là những người trong danh sách dự kiến bầu, bổ nhiệm làm Chủ tịch và các thành viên khác của Hội đồng quản trị, Trưởng ban và các thành viên khác của Ban kiểm soát, Giám đốc của quỹ tín dụng nhân dân nhiệm kỳ đầu tiên và một số thành viên khác để thay mặt các thành viên sáng lập triển khai các công việc liên quan đến đề nghị chấp thuận nguyên tắc việc thành lập quỹ tín dụng nhân dân và sửa đổi, bổ sung hồ sơ đề nghị cấp Giấy phép trong trường hợp Ngân hàng Nhà nước Khu vực có yêu cầu;","d"],["p","c) Quyết định các vấn đề khác liên quan đến việc thành lập quỹ tín dụng nhân dân.","d"],["p","4. <i>Giấy phép</i> là Giấy phép thành lập và hoạt động của quỹ tín dụng nhân dân do Ngân hàng Nhà nước Khu vực cấp. Giấy phép đồng thời là Giấy chứng nhận đăng ký hợp tác xã. Văn bản của Ngân hàng Nhà nước về sửa đổi, bổ sung Giấy phép là một bộ phận không tách rời của Giấy phép.","k"],["p","5. Đại hội thành viên đầu tiên là đại hội của tất cả các thành viên sáng lập quỹ tín dụng nhân dân được tổ chức sau khi được Ngân hàng Nhà nước Khu vực chấp thuận nguyên tắc việc thành lập, có nhiệm vụ:","k"],["p","a) Thông qua Điều lệ của quỹ tín dụng nhân dân;","d"],["p","b) Bầu Chủ tịch và các thành viên khác của Hội đồng quản trị, Trưởng ban và các thành viên khác của Ban kiểm soát nhiệm kỳ đầu tiên theo danh sách nhân sự dự kiến đã được Ngân hàng Nhà nước Khu vực chấp thuận;","d"],["p","c) Thông qua các quy định về tổ chức và hoạt động của Hội đồng quản trị, Ban kiểm soát quỹ tín dụng nhân dân;","d"],["p","d) Thông qua chủ trương thành viên Hội đồng quản trị kiêm Giám đốc hoặc thuê Giám đốc;","d"],["p","đ) Quyết định các vấn đề khác liên quan đến việc thành lập quỹ tín dụng nhân dân.","d"]]},{"id":"dieu-4","so":"4","ten":"Thẩm quyền cấp Giấy phép lần đầu, cấp đổi Giấy phép, cấp bản sao Giấy phép từ sổ gốc","nd":[["p","Giám đốc Ngân hàng Nhà nước Khu vực có thẩm quyền quyết định cấp Giấy phép <b>lần đầu, cấp đổi Giấy phép, cấp bản sao Giấy phép từ sổ gốc</b> đối với quỹ tín dụng nhân dân có trụ sở chính đặt trên địa bàn.",""]]},{"id":"dieu-5","so":"5","ten":"Nguyên tắc lập và gửi hồ sơ","nd":[["p","1. Các văn bản tại hồ sơ đề nghị cấp Giấy phép lần đầu phải do Trưởng ban trù bị ký, trừ trường hợp Thông tư này có quy định khác. Các văn bản do Trưởng ban trù bị ký phải có tiêu đề “Ban trù bị thành lập quỹ tín dụng nhân dân … (tên quỹ tín dụng nhân dân) đề nghị cấp phép”.","k"],["p","2. Các văn bản tại hồ sơ đề nghị cấp đổi Giấy phép, cấp bản sao Giấy phép từ sổ gốc phải do người đại diện theo pháp luật hoặc người đại diện theo ủy quyền ký (sau đây gọi là người đại diện hợp pháp). Trường hợp ký theo ủy quyền, hồ sơ phải có văn bản ủy quyền được lập phù hợp với quy định của pháp luật.","k"],["p","3. Hồ sơ đề nghị cấp Giấy phép lần đầu, cấp đổi Giấy phép, cấp bản sao Giấy phép từ sổ gốc của quỹ tín dụng nhân dân được lập 01 bộ bằng tiếng Việt.","k"],["p","4. Đối với thành phần hồ sơ là bản sao, quỹ tín dụng nhân dân nộp bản sao được cấp từ sổ gốc hoặc bản sao có chứng thực hoặc bản sao kèm xuất trình bản chính để đối chiếu. Trong trường hợp người nộp hồ sơ nộp bản sao kèm xuất trình bản chính để đối chiếu, người đối chiếu phải ký xác nhận vào bản sao và chịu trách nhiệm về tính chính xác của bản sao so với bản chính.","k"],["p","5. Trong mỗi bộ hồ sơ phải có danh mục tài liệu.","k"],["p","6. Hồ sơ cấp Giấy phép lần đầu, cấp đổi Giấy phép được nộp trực tiếp hoặc gửi qua dịch vụ bưu chính đến Bộ phận Một cửa của Ngân hàng Nhà nước Khu vực.","k"]]},{"id":"dieu-6","so":"6","ten":"Giấy phép","nd":[["p","1. Ngân hàng Nhà nước Khu vực quy định cụ thể nội dung hoạt động, địa bàn hoạt động, thời hạn hoạt động trong Giấy phép theo mẫu quy định tại Phụ lục số 01 ban hành kèm theo Thông tư này.","k"],["p","2. Trường hợp Giấy phép bị mất, bị rách nát, bị cháy, hư hỏng, quỹ tín dụng nhân dân có đơn đề nghị cấp bản sao Giấy phép từ sổ gốc theo mẫu quy định tại Phụ lục số 02 ban hành kèm theo Thông tư này, gửi trực tiếp hoặc qua dịch vụ bưu chính đến Bộ phận Một cửa của Ngân hàng Nhà nước Khu vực hoặc nộp trực tuyến qua Cổng dịch vụ công Ngân hàng Nhà nước Việt Nam (sau đây gọi là Ngân hàng Nhà nước) đề nghị xem xét cấp bản sao Giấy phép từ sổ gốc theo quy định của pháp luật.","k"],["p","Trong thời hạn 04 ngày làm việc kể từ ngày nhận được đơn đề nghị, Ngân hàng Nhà nước Khu vực xem xét, cấp bản sao Giấy phép từ sổ gốc cho quỹ tín dụng nhân dân.",""]]},{"id":"dieu-7","so":"7","ten":"Nộp lệ phí cấp Giấp phép","nd":[["p","1. Quỹ tín dụng nhân dân được cấp Giấy phép lần đầu, cấp đổi Giấy phép phải nộp lệ phí cấp Giấy phép lần đầu, cấp đổi Giấy phép tại Ngân hàng Nhà nước Khu vực hoặc thanh toán trực tuyến trên Cổng Dịch vụ công quốc gia trong thời hạn 15 ngày kể từ ngày được cấp Giấy phép lần đầu, cấp đổi Giấy phép.","k"],["p","2. Mức lệ phí cấp Giấy phép lần đầu, cấp đổi Giấy phép theo quy định của pháp luật về phí và lệ phí.","k"]]}]},{"id":"c2","title":"Chương II — QUY ĐỊNH CỤ THỂ","articles":[{"id":"muc-0","muc":"Mục 1","ten":"QUY ĐỊNH VỀ CẤP GIẤY PHÉP LẦN ĐẦU","nd":[]},{"id":"dieu-8","so":"8","ten":"Hồ sơ đề nghị cấp Giấy phép lần đầu","nd":[["p","1. Đơn đề nghị cấp Giấy phép theo mẫu quy định tại Phụ lục số 03 ban hành kèm theo Thông tư này.","k"],["p","2. Dự thảo Điều lệ quỹ tín dụng nhân dân được Hội nghị thành lập thông qua.","k"],["p","3. Đề án thành lập quỹ tín dụng nhân dân được Hội nghị thành lập thông qua, trong đó nêu rõ:","k"],["p","a) Sự cần thiết thành lập quỹ tín dụng nhân dân;","d"],["p","b) Tên quỹ tín dụng nhân dân, địa bàn hoạt động, địa điểm dự kiến đặt trụ sở chính, thời hạn hoạt động, vốn điều lệ khi thành lập, nội dung hoạt động phù hợp với quy định tại Luật Các tổ chức tín dụng và các quy định liên quan của pháp luật;","d"],["p","c) Cơ cấu tổ chức;","d"],["p","d) Quy định về quản lý rủi ro, trong đó nêu rõ các loại rủi ro có thể xảy ra trong quá trình hoạt động, phương thức và biện pháp phòng ngừa, kiểm soát các loại rủi ro này;","d"],["p","đ) Quy trình, chính sách cho vay đối với thành viên, người có tiền gửi tại quỹ tín dụng nhân dân, hộ nghèo trên địa bàn không phải là thành viên của quỹ tín dụng nhân dân;","d"],["p","e) Công nghệ thông tin: Dự kiến hệ thống công nghệ thông tin đảm bảo an toàn, bảo mật thông tin, hỗ trợ hoạt động nghiệp vụ, quản trị và các yêu cầu báo cáo, thống kê; khả năng áp dụng hệ thống công nghệ thông tin trong hoạt động ngân hàng và việc đầu tư cho hệ thống công nghệ thông tin;","d"],["p","g) Dự kiến hệ thống kiểm soát, kiểm toán nội bộ phù hợp với quy định của Thống đốc Ngân hàng Nhà nước:","d"],["p","(i) Nguyên tắc hoạt động của hệ thống kiểm soát nội bộ;",""],["p","(ii) Dự thảo các quy định nội bộ về tổ chức và hoạt động của quỹ tín dụng nhân dân, tối thiểu gồm các quy định nội bộ quy định tại khoản 2 Điều 101 Luật Các tổ chức tín dụng và các quy định về tổ chức và hoạt động của Hội đồng quản trị, Ban kiểm soát, Người điều hành;",""],["p","(iii) Nội dung và quy trình hoạt động của kiểm toán nội bộ;",""],["p","h) Phương án kinh doanh dự kiến trong 03 năm đầu phù hợp với nội dung, phạm vi hoạt động, trong đó phân tích, thuyết minh tính hiệu quả và khả năng thực hiện phương án trong từng năm.","d"],["p","4. Danh sách nhân sự dự kiến bầu, bổ nhiệm làm Chủ tịch và thành viên Hội đồng quản trị, Trưởng ban và thành viên Ban kiểm soát, Giám đốc quỹ tín dụng nhân dân.","k"],["p","5. Tài liệu chứng minh về việc đáp ứng tiêu chuẩn, điều kiện của những người dự kiến bầu, bổ nhiệm làm Chủ tịch và thành viên Hội đồng quản trị, Trưởng ban và thành viên Ban kiểm soát, Giám đốc quỹ tín dụng nhân dân gồm:","k"],["p","a) Sơ yếu lý lịch theo mẫu quy định tại Phụ lục số 04 ban hành kèm theo Thông tư này;","d"],["p","b) Bản sao các văn bằng chứng minh trình độ, chuyên môn;","d"],["p","c) Phiếu lý lịch tư pháp, đảm bảo các quy định sau:","d"],["p","(i) Phải có đầy đủ thông tin về tình trạng án tích (bao gồm án tích đã được xóa và án tích chưa được xóa) và thông tin về việc đảm nhiệm chức vụ, thành lập, quản lý doanh nghiệp, hợp tác xã;",""],["p","(ii) Phải được cơ quan có thẩm quyền cấp trước thời điểm nộp hồ sơ đề nghị cấp Giấy phép không quá 06 tháng.",""],["p","Nhân sự dự kiến bầu, bổ nhiệm có thể xuất trình Phiếu lý lịch tư pháp bản điện tử đã được cấp trên ứng dụng định danh và xác thực điện tử VNeID hoặc nộp Phiếu lý lịch tư pháp bản điện tử theo quy định của pháp luật;",""],["p","d) Bản kê khai người có liên quan của nhân sự dự kiến bầu, bổ nhiệm; văn bản đánh giá về việc nhân sự dự kiến bầu, bổ nhiệm có đạo đức nghề nghiệp của tổ chức tín dụng, chi nhánh ngân hàng nước ngoài nơi nhân sự dự kiến đã, đang công tác theo quy định của Thống đốc Ngân hàng Nhà nước về chấp thuận danh sách nhân sự dự kiến.","d"],["p","6. Danh sách các thành viên sáng lập quỹ tín dụng nhân dân. Danh sách phải được tất cả thành viên sáng lập ký xác nhận, có tối thiểu các nội dung sau:","k"],["p","a) Họ và tên (đối với thành viên là cá nhân, người đại diện hộ gia đình); Tên, địa chỉ đặt trụ sở chính (đối với thành viên là pháp nhân);","d"],["p","b) Số định danh cá nhân đối với thành viên là cá nhân; số định danh cá nhân của người đại diện gia đình đối với thành viên là hộ gia đình; mã số doanh nghiệp hoặc số Quyết định thành lập hoặc số giấy tờ khác có giá trị tương đương và số định danh cá nhân của người đại diện phần vốn góp đối với thành viên là pháp nhân;","d"],["p","c) Số tiền tham gia góp vốn, tỷ lệ góp vốn của từng thành viên.","d"],["p","7. Bản sao Giấy chứng nhận đăng ký doanh nghiệp hoặc Quyết định thành lập hoặc giấy tờ có giá trị tương đương (đối với thành viên là pháp nhân).","k"],["p","8. Văn bản ủy quyền của pháp nhân cho người đại diện của pháp nhân tham gia góp vốn.","k"],["p","9. Văn bản ủy quyền của hộ gia đình cho người đại diện hộ gia đình tham gia góp vốn.","k"],["p","10. Báo cáo tài chính năm liền kề năm đề nghị cấp Giấy phép và Báo cáo tài chính đến thời điểm gần nhất nhưng không quá 90 ngày trở về trước tính từ thời điểm ký đơn đề nghị cấp Giấy phép (đối với thành viên là pháp nhân).","k"],["p","11. Báo cáo khả năng tài chính để tham gia góp vốn thành lập quỹ tín dụng nhân dân đối với pháp nhân theo mẫu quy định tại Phụ lục số 05 ban hành kèm theo Thông tư này.","k"],["p","12. Đơn đề nghị tham gia thành viên theo quy định của Thống đốc Ngân hàng Nhà nước về quỹ tín dụng nhân dân.","k"],["p","13. Biên bản Hội nghị thành lập thông qua dự thảo Điều lệ; Đề án thành lập quỹ tín dụng nhân dân; danh sách nhân sự dự kiến bầu, bổ nhiệm làm Chủ tịch và thành viên Hội đồng quản trị, Trưởng ban và thành viên Ban kiểm soát, Giám đốc quỹ tín dụng nhân dân và lựa chọn Ban trù bị, Trưởng Ban trù bị.","k"],["p","14. Sau khi nhận được văn bản chấp thuận nguyên tắc, Ban trù bị phải nộp bổ sung các văn bản sau:","k"],["p","a) Điều lệ của quỹ tín dụng nhân dân đã được Đại hội thành viên đầu tiên quỹ tín dụng nhân dân thông qua;","d"],["p","b) Biên bản họp và Nghị quyết của Đại hội thành viên đầu tiên quỹ tín dụng nhân dân về việc thông qua Điều lệ, bầu Chủ tịch và các thành viên khác của Hội đồng quản trị, Trưởng ban và các thành viên khác của Ban kiểm soát; chủ trương thành viên Hội đồng quản trị kiêm Giám đốc hoặc thuê Giám đốc. Nghị quyết của Đại hội thành viên đầu tiên về việc thông qua Điều lệ phải được ít nhất 75% tổng số phiếu biểu quyết tán thành của thành viên tham dự. Nghị quyết của Đại hội thành viên đầu tiên về việc thông qua bầu Chủ tịch và các thành viên khác của Hội đồng quản trị, Trưởng ban và các thành viên khác của Ban kiểm soát; chủ trương thành viên Hội đồng quản trị kiêm Giám đốc hoặc thuê Giám đốc phải được trên 50% tổng số phiếu biểu quyết tán thành của thành viên tham dự;","d"],["p","c) Quyết định của Hội đồng quản trị quỹ tín dụng nhân dân về việc bổ nhiệm Giám đốc quỹ tín dụng nhân dân theo danh sách nhân sự dự kiến đã được Ngân hàng Nhà nước Khu vực chấp thuận;","d"],["p","d) Văn bản chứng minh quyền sở hữu hoặc quyền sử dụng hợp pháp địa điểm đặt trụ sở chính;","d"],["p","đ) Các quy định nội bộ về tổ chức và hoạt động của quỹ tín dụng nhân dân quy định tại điểm g(ii) khoản 3 Điều 8 Thông tư này đã được Đại hội thành viên đầu tiên, Hội đồng quản trị thông qua.","d"]]},{"id":"dieu-9","so":"9","ten":"Trình tự cấp Giấy phép lần đầu","nd":[["p","1. Ngân hàng Nhà nước Khu vực khai thác các thông tin cần thiết trong Cơ sở dữ liệu quốc gia về dân cư khi xem xét, thẩm định thông tin về cư trú. Trong trường hợp không khai thác được các thông tin cần thiết trong Cơ sở dữ liệu quốc gia về dân cư, Ngân hàng Nhà nước Khu vực có quyền yêu cầu Ban trù bị cung cấp bản sao một trong các giấy tờ có giá trị chứng minh thông tin về cư trú theo quy định của pháp luật về khai thác, sử dụng thông tin về cư trú để giải quyết thủ tục hành chính, cung cấp dịch vụ công.","k"],["p","2. Ban trù bị lập hồ sơ đề nghị cấp Giấy phép theo quy định từ khoản 1 đến khoản 13 Điều 8 Thông tư này và gửi Ngân hàng Nhà nước Khu vực.","k"],["p","Trong thời hạn 30 ngày kể từ ngày nhận được hồ sơ đề nghị cấp Giấy phép tại khoản này, Ngân hàng Nhà nước Khu vực có văn bản gửi Ban trù bị xác nhận đã nhận đủ hồ sơ hợp lệ để xem xét chấp thuận nguyên tắc. Trường hợp hồ sơ đề nghị cấp Giấy phép không đầy đủ, Ngân hàng Nhà nước Khu vực có văn bản gửi Ban trù bị yêu cầu bổ sung hồ sơ.",""],["p","3. Trong 05 ngày làm việc kể từ ngày xác nhận đã nhận đủ hồ sơ hợp lệ theo quy định tại khoản 2 Điều này, Ngân hàng Nhà nước Khu vực có văn bản gửi lấy ý kiến của:","k"],["p","a) Ủy ban nhân dân xã, phường hoặc Ủy ban nhân dân cấp cơ sở trực thuộc tỉnh, thành phố trực thuộc Trung ương (sau đây gọi là Ủy ban nhân dân cấp xã) nơi quỹ tín dụng nhân dân đề nghị thành lập dự kiến đặt trụ sở chính về việc thành lập quỹ tín dụng nhân dân trên địa bàn;","d"],["p","b) Ủy ban nhân dân cấp xã nơi nhân sự dự kiến bầu, bổ nhiệm cư trú về danh sách nhân sự dự kiến bầu, bổ nhiệm làm Chủ tịch và các thành viên khác của Hội đồng quản trị, Trưởng ban và các thành viên khác của Ban kiểm soát, Giám đốc quỹ tín dụng nhân dân đề nghị thành lập;","d"],["p","c) Ngân hàng Nhà nước Khu vực khác đề nghị cung cấp thông tin theo mẫu quy định tại Phụ lục số 06 ban hành kèm theo Thông tư này (nếu thấy cần thiết);","d"],["p","d) Ngân hàng hợp tác xã về danh sách nhân sự dự kiến bầu, bổ nhiệm làm Chủ tịch và các thành viên khác của Hội đồng quản trị, Trưởng ban và các thành viên khác của Ban kiểm soát, Giám đốc quỹ tín dụng nhân dân đề nghị thành lập (nếu thấy cần thiết).","d"],["p","4. Trong thời hạn 15 ngày kể từ ngày nhận được văn bản đề nghị của Ngân hàng Nhà nước Khu vực, các đơn vị được lấy ý kiến có văn bản tham gia ý kiến.","k"],["p","5. Trong thời hạn 45 ngày kể từ ngày gửi văn bản xác nhận đã nhận đầy đủ hồ sơ hợp lệ, Ngân hàng Nhà nước Khu vực có văn bản chấp thuận nguyên tắc thành lập quỹ tín dụng nhân dân. Trường hợp không chấp thuận, Ngân hàng Nhà nước Khu vực có văn bản trả lời Ban trù bị, trong đó nêu rõ lý do không chấp thuận. Nội dung văn bản chấp thuận nguyên tắc bao gồm: chấp thuận nguyên tắc thành lập và hoạt động quỹ tín dụng nhân dân; chấp thuận danh sách nhân sự dự kiến của quỹ tín dụng nhân dân.","k"],["p","6<i>. </i>Trong thời hạn 60 ngày kể từ ngày nhận được văn bản chấp thuận nguyên tắc thành lập quỹ tín dụng nhân dân:","k"],["p","a) Ban trù bị tổ chức cuộc họp Đại hội thành viên đầu tiên để thông qua các nội dung theo quy định tại khoản 5 Điều 3 Thông tư này;","d"],["p","b) Ban trù bị lập các văn bản bổ sung theo quy định tại khoản 14 Điều 8 Thông tư này và gửi Ngân hàng Nhà nước Khu vực. Quá thời hạn nêu trên, Ngân hàng Nhà nước Khu vực không nhận được hoặc nhận được không đầy đủ các văn bản nêu trên thì văn bản chấp thuận nguyên tắc không còn giá trị.","d"],["p","Trong thời hạn 05 ngày làm việc kể từ ngày nhận được đầy đủ các văn bản bổ sung, Ngân hàng Nhà nước Khu vực xác nhận bằng văn bản về việc đã nhận đầy đủ văn bản. Trong thời hạn 30 ngày kể từ ngày Ngân hàng Nhà nước Khu vực xác nhận bằng văn bản về việc nhận đầy đủ các văn bản bổ sung, Ngân hàng Nhà nước Khu vực tiến hành cấp Giấy phép theo quy định. Trường hợp không cấp Giấy phép, Ngân hàng Nhà nước Khu vực có văn bản nêu rõ lý do không cấp Giấy phép.",""]]},{"id":"dieu-10","so":"10","ten":"Khai trương hoạt động","nd":[["p","1. Quỹ tín dụng nhân dân phải niêm yết tại trụ sở Ủy ban nhân dân cấp xã, thông báo trên đài truyền thanh cấp xã nơi đặt trụ sở chính (nếu có) trong 03 ngày liên tiếp, công bố trên 01 phương tiện truyền thông của Ngân hàng Nhà nước và trên 01 tờ báo in trong 03 số liên tiếp hoặc trên 01 báo điện tử của Việt Nam ít nhất 30 ngày trước ngày dự kiến khai trương hoạt động các thông tin sau đây:","k"],["p","a) Tên, địa chỉ đặt trụ sở chính;","d"],["p","b) Số, ngày cấp Giấy phép;","d"],["p","c) Nội dung hoạt động, thời hạn hoạt động, địa bàn hoạt động;","d"],["p","d) Vốn điều lệ;","d"],["p","đ) Người đại diện theo pháp luật;","d"],["p","e) Danh sách và tỷ lệ góp vốn tương ứng của từng thành viên sáng lập quỹ tín dụng nhân dân;","d"],["p","g) Ngày dự kiến khai trương hoạt động.","d"],["p","2. Để khai trương hoạt động, quỹ tín dụng nhân dân đã được cấp Giấy phép phải có đủ các điều kiện sau đây:","k"],["p","a) Đã gửi Ngân hàng Nhà nước Khu vực Điều lệ của quỹ tín dụng nhân dân được Đại hội thành viên đầu tiên thông qua;","d"],["p","b) Có đủ vốn điều lệ. Vốn điều lệ bằng đồng Việt Nam phải được gửi đầy đủ vào tài khoản phong tỏa không hưởng lãi mở tại Ngân hàng Nhà nước Khu vực ít nhất 30 ngày trước ngày khai trương hoạt động. Vốn điều lệ được giải tỏa khi quỹ tín dụng nhân dân đã khai trương hoạt động;","d"],["p","c) Có trụ sở chính đáp ứng các điều kiện sau:","d"],["p","(i) Là nơi làm việc của Hội đồng quản trị, Ban điều hành, được ghi trong Giấy phép theo quy định của pháp luật và được thực hiện giao dịch với khách hàng;",""],["p","(ii) Nằm trên địa bàn hoạt động được quy định trong Giấy phép, có địa chỉ được xác định gồm tên tòa nhà, số nhà, ngách, hẻm, ngõ phố, phố, đường hoặc thôn, xóm, ấp, xã, phường, tỉnh, thành phố trực thuộc Trung ương; số điện thoại, số fax và thư điện tử (nếu có);",""],["p","(iii) Thuộc quyền sở hữu hoặc sử dụng hợp pháp của quỹ tín dụng nhân dân;",""],["p","(iv) Đảm bảo thuận tiện giao dịch với khách hàng và có kho tiền đảm bảo tiêu chuẩn kỹ thuật theo quy định của Thống đốc Ngân hàng Nhà nước;",""],["p","(v) Đảm bảo an toàn tài sản và phù hợp với yêu cầu hoạt động của quỹ tín dụng nhân dân;",""],["p","d) Có cơ cấu tổ chức quản lý, hệ thống kiểm soát nội bộ, kiểm toán nội bộ phù hợp với loại hình hoạt động theo quy định của Luật Các tổ chức tín dụng và quy định khác của pháp luật có liên quan;","d"],["p","đ) Có hệ thống công nghệ thông tin đáp ứng yêu cầu tại điểm e khoản 3 Điều 8 Thông tư này;","d"],["p","e) Có quy định nội bộ về tổ chức, hoạt động của Hội đồng quản trị, Ban kiểm soát, Giám đốc, bộ phận chuyên môn nghiệp vụ; quy định nội bộ về quản lý rủi ro;","d"],["p","g) Đã công bố thông tin về khai trương hoạt động theo quy định tại khoản 1 Điều này.","d"],["p","3. Quỹ tín dụng nhân dân phải tiến hành khai trương hoạt động trong thời hạn 12 tháng kể từ ngày được cấp Giấy phép, trừ trường hợp có sự kiện bất khả kháng; quá thời hạn này mà không khai trương hoạt động thì Giấy phép đã cấp hết hiệu lực. Ngân hàng Nhà nước công bố trên Cổng thông tin điện tử Ngân hàng Nhà nước về Giấy phép của quỹ tín dụng nhân dân hết hiệu lực.","k"],["p","4. Ít nhất 15 ngày trước ngày dự kiến khai trương hoạt động, quỹ tín dụng nhân dân được cấp Giấy phép phải thông báo bằng văn bản về các điều kiện khai trương hoạt động quy định tại khoản 2 Điều này, gửi trực tiếp hoặc qua dịch vụ bưu chính đến Ngân hàng Nhà nước Khu vực. Ngân hàng Nhà nước Khu vực đình chỉ việc khai trương hoạt động của quỹ tín dụng nhân dân khi không đủ các điều kiện quy định tại khoản 2 Điều này.","k"]]},{"id":"muc-4","muc":"Mục 2","ten":"QUY ĐỊNH VỀ CẤP ĐỔI GIẤY PHÉP","nd":[]},{"id":"dieu-11","so":"11","ten":"Nguyên tắc cấp đổi Giấy phép","nd":[["p","1. Ngân hàng Nhà nước Khu vực không thực hiện cấp đổi đối với các nội dung hoạt động mà quỹ tín dụng nhân dân không được phép thực hiện theo quy định của pháp luật tại thời điểm cấp đổi.","k"],["p","2. Ngân hàng Nhà nước Khu vực điều chỉnh tên nội dung hoạt động được phép thực hiện phù hợp với quy định của Luật Các tổ chức tín dụng. Giấy phép được cấp đổi theo mẫu quy định tại Phụ lục số 07 ban hành kèm theo Thông tư này thay thế tất cả các Giấy phép, các văn bản sửa đổi bổ sung Giấy phép có liên quan mà Ngân hàng Nhà nước đã cấp cho quỹ tín dụng nhân dân đó trước thời điểm cấp đổi.","k"],["p","3. Trường hợp quỹ tín dụng nhân dân đề nghị bổ sung nội dung hoạt động vào Giấy phép đồng thời với cấp đổi Giấy phép, Ngân hàng Nhà nước Khu vực sẽ xem xét cấp đổi Giấy phép trong đó bao gồm nội dung bổ sung theo đề nghị trên cơ sở quỹ tín dụng nhân dân đáp ứng đầy đủ hồ sơ theo quy định tại khoản 1 Điều 12 Thông tư này.","k"]]},{"id":"dieu-12","so":"12","ten":"Hồ sơ, trình tự đề nghị cấp đổi Giấy phép","nd":[["p","1. Hồ sơ đề nghị cấp đổi Giấy phép:","k"],["p","a) Đơn đề nghị cấp đổi Giấy phép theo mẫu quy định tại Phụ lục số 08 ban hành kèm theo Thông tư này;","d"],["p","b) Hồ sơ đề nghị thay đổi nội dung hoạt động (trường hợp quỹ tín dụng nhân dân đề nghị bổ sung nội dung hoạt động đồng thời với cấp đổi Giấy phép):","d"],["p","(i) Nghị quyết của Đại hội thành viên thông qua việc thay đổi nội dung hoạt động;",""],["p","(ii) Phương án triển khai nội dung hoạt động, tối thiểu bao gồm các nội dung: Mô tả nội dung, quy trình thực hiện, phân tích hiệu quả và biện pháp phòng ngừa, kiểm soát rủi ro, kế hoạch triển khai thực hiện; phương án xử lý, đảm bảo quy định về các tỷ lệ đảm bảo an toàn trong hoạt động của tổ chức tín dụng là hợp tác xã (trường hợp đề nghị chấp thuận thu hẹp nội dung hoạt động);",""],["p","(iii) Quy định nội bộ về quy trình triển khai nghiệp vụ đảm bảo quản lý và kiểm soát rủi ro phát sinh;",""],["p","(iv) Tài liệu chứng minh việc đáp ứng điều kiện liên quan đến nội dung hoạt động đề nghị theo quy định của pháp luật (nếu có).",""],["p","2. Trình tự đề nghị cấp đổi Giấy phép:","k"],["p","a) Quỹ tín dụng nhân dân có nhu cầu cấp đổi Giấy phép lập hồ sơ theo quy định tại khoản 1 Điều này và gửi Ngân hàng Nhà nước Khu vực;","d"],["p","b) Trong thời hạn 30 ngày kể từ ngày nhận được hồ sơ đầy đủ và hợp lệ của quỹ tín dụng nhân dân, Ngân hàng Nhà nước Khu vực thực hiện việc cấp đổi Giấy phép (bao gồm cả bổ sung nội dung hoạt động đồng thời với cấp đổi Giấy phép) theo đề nghị cho quỹ tín dụng nhân dân. Trường hợp từ chối, Ngân hàng Nhà nước Khu vực trả lời bằng văn bản và nêu rõ lý do.","d"]]},{"id":"muc-7","muc":"Mục 3","ten":"THÔNG BÁO THÔNG TIN VỀ CẤP GIẤY PHÉP LẦN ĐẦU, CẤP ĐỔI GIẤY PHÉP","nd":[]},{"id":"dieu-13","so":"13","ten":"Thông báo thông tin về cấp Giấy phép lần đầu, cấp đổi Giấy phép cho cơ quan đăng ký kinh doanh","nd":[["p","1. Trong thời hạn 05 ngày làm việc kể từ ngày cấp Giấy phép lần đầu, Ngân hàng Nhà nước Khu vực có trách nhiệm thông báo bằng văn bản kèm Giấy phép, thông tin về người đại diện theo pháp luật của quỹ tín dụng nhân dân cho cơ quan đăng ký kinh doanh theo quy định về đăng ký hợp tác xã để cập nhật vào hệ thống thông tin quốc gia về đăng ký hợp tác xã.","k"],["p","2. Trong thời hạn 05 ngày làm việc kể từ ngày cấp đổi Giấy phép, Ngân hàng Nhà nước Khu vực có trách nhiệm thông báo bằng văn bản kèm Giấy phép cấp đổi cho cơ quan đăng ký kinh doanh theo quy định về đăng ký hợp tác xã để cập nhật vào hệ thống thông tin quốc gia về đăng ký hợp tác xã.","k"]]}]},{"id":"c3","title":"Chương III — TRÁCH NHIỆM CỦA CÁC TỔ CHỨC, CÁ NHÂN CÓ LIÊN QUAN","articles":[{"id":"dieu-14","so":"14","ten":"Trách nhiệm của Ban trù bị","nd":[["p","1. Lập và gửi hồ sơ đề nghị cấp Giấy phép lần đầu theo quy định tại Thông tư này.","k"],["p","2. Sau khi nhận được văn bản chấp thuận nguyên tắc, Ban trù bị có trách nhiệm:","k"],["p","a) Tổ chức cuộc họp Đại hội thành viên đầu tiên theo quy định tại điểm a khoản 6 Điều 9 Thông tư này;","d"],["p","b) Thông báo cho các thành viên sáng lập gửi tiền vào tài khoản do Ban trù bị mở tại một ngân hàng thương mại Việt Nam.","d"],["p","3. Hướng dẫn thành viên sáng lập thực hiện việc góp vốn và thẩm định hồ sơ của thành viên sáng lập.","k"],["p","4. Chịu trách nhiệm về tính đầy đủ, chính xác của nội dung hồ sơ đã nộp cho Ngân hàng Nhà nước Khu vực.","k"],["p","5. Thông báo cho các thành viên sáng lập biết lý do không được cấp Giấy phép trong trường hợp không được Ngân hàng Nhà nước Khu vực chấp thuận.","k"]]},{"id":"dieu-15","so":"15","ten":"Trách nhiệm của Trưởng Ban trù bị","nd":[["p","1. Triệu tập cuộc họp Đại hội thành viên đầu tiên theo quy định của pháp luật.","k"],["p","2. Ký các văn bản thuộc thẩm quyền có liên quan đến việc thành lập quỹ tín dụng nhân dân cho đến khi được Ngân hàng Nhà nước Khu vực cấp Giấy phép.","k"]]},{"id":"dieu-16","so":"16","ten":"Trách nhiệm của tổ chức, cá nhân có liên quan đến việc thành lập quỹ tín dụng nhân dân","nd":[["p","Tổ chức, cá nhân có liên quan đến việc thành lập quỹ tín dụng nhân dân phải cung cấp đầy đủ, chính xác, kịp thời các thông tin theo yêu cầu của Ngân hàng Nhà nước Khu vực, Ban trù bị theo quy định tại Thông tư này và chịu trách nhiệm trước pháp luật về các thông tin trên.",""]]},{"id":"dieu-17","so":"17","ten":"Trách nhiệm của quỹ tín dụng nhân dân","nd":[["p","1. Cung cấp đầy đủ, chính xác, kịp thời các thông tin theo yêu cầu của Ngân hàng Nhà nước Khu vực theo quy định tại Thông tư này về việc cấp đổi Giấy phép và chịu hoàn toàn trách nhiệm trước pháp luật về các thông tin trên.","k"],["p","2. Quỹ tín dụng nhân dân phải niêm yết tại trụ sở Ủy ban nhân dân cấp xã, thông báo trên đài truyền thanh cấp xã nơi đặt trụ sở chính (nếu có) trong 03 ngày liên tiếp, công bố trên 01 phương tiện truyền thông của Ngân hàng Nhà nước và trên 01 tờ báo in trong 03 số liên tiếp hoặc trên 01 báo điện tử của Việt Nam về việc cấp đổi Giấy phép trong thời hạn 07 ngày làm việc kể từ ngày được Ngân hàng Nhà nước Khu vực cấp đổi Giấy phép và thực hiện sửa đổi, bổ sung Điều lệ phù hợp với nội dung Giấy phép cấp đổi.","k"],["p","3. Thực hiện các nội dung khác theo quy định tại Thông tư này.","k"]]},{"id":"dieu-18","so":"18","ten":"Trách nhiệm của Ngân hàng Nhà nước Khu vực","nd":[["p","1. Thẩm định tính đầy đủ, hợp lệ của hồ sơ đề nghị cấp Giấy phép quỹ tín dụng nhân dân trước khi chấp thuận nguyên tắc và có văn bản gửi Ban trù bị để xác nhận hồ sơ đầy đủ, hợp lệ hoặc yêu cầu bổ sung hồ sơ.","k"],["p","2. Cấp Giấy phép cho quỹ tín dụng nhân dân nếu đủ điều kiện và đảm bảo đủ hồ sơ theo quy định tại Thông tư này hoặc có văn bản từ chối không cấp Giấy phép cho quỹ tín dụng nhân dân (trong đó nêu rõ lý do).","k"],["p","3. Chịu trách nhiệm về quản lý và lưu trữ hồ sơ cấp Giấy phép lần đầu, cấp đổi Giấy phép sau khi đã cấp Giấy phép lần đầu, cấp đổi Giấy phép.","k"],["p","4. Kiểm tra, chỉ đạo, giám sát quỹ tín dụng nhân dân thực hiện và đảm bảo các điều kiện theo quy định của pháp luật, của Ngân hàng Nhà nước trước khi tiến hành khai trương hoạt động.","k"],["p","5. Đình chỉ quỹ tín dụng nhân dân khai trương hoạt động trong trường hợp quỹ tín dụng nhân dân không đáp ứng các điều kiện khai trương hoạt động.","k"],["p","6. Thẩm định hồ sơ đề nghị cấp đổi Giấy phép của quỹ tín dụng nhân dân. Cấp đổi Giấy phép cho quỹ tín dụng nhân dân hoặc có văn bản từ chối không cấp đổi Giấy phép cho quỹ tín dụng nhân dân (trong đó nêu rõ lý do).","k"],["p","7. <i>Có văn bản gửi Ngân hàng Nhà nước để công bố trên Cổng thông tin điện tử Ngân hàng Nhà nước về Giấy phép của quỹ tín dụng nhân dân hết hiệu lực theo quy định tại khoản 3 Điều 10 Thông tư này .</i>","k"]]},{"id":"dieu-19","so":"19","ten":"Trách nhiệm của ngân hàng hợp tác xã","nd":[["p","Tham gia ý kiến bằng văn bản đối với danh sách nhân sự dự kiến bầu, bổ nhiệm làm Chủ tịch và các thành viên khác của Hội đồng quản trị, Trưởng ban và các thành viên khác của Ban kiểm soát, Giám đốc quỹ tín dụng nhân dân khi Ngân hàng Nhà nước Khu vực yêu cầu.",""]]}]},{"id":"c4","title":"Chương IV — ĐIỀU KHOẢN THI HÀNH","articles":[{"id":"dieu-20","so":"20","ten":"Hiệu lực thi hành","nd":[["p","Thông tư này có hiệu lực thi hành từ ngày 15 tháng 6 năm 2025.",""]]},{"id":"dieu-21","so":"21","ten":"Tổ chức thực hiện","nd":[["p","Thủ trưởng các đơn vị thuộc Ngân hàng Nhà nước, Giám đốc Ngân hàng Nhà nước Khu vực, ngân hàng hợp tác xã, quỹ tín dụng nhân dân chịu trách nhiệm tổ chức thực hiện Thông tư này./.",""],["p","<b>KT. THỐNG ĐỐC PHÓ THỐNG ĐỐC</b>",""],["p","<b>Đoàn Thái Sơn</b>",""]]}]},{"id":"c5","title":"Phụ lục số 01 — Mẫu Giấy phép","articles":[{"id":"pl-5","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số 01/2025/TT-NHNN ngày 29/4/2025 của </i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam quy định về cấp Giấy phép lần đầu,</i>",""],["p","<i>cấp đổi Giấy phép của quỹ tín dụng nhân dân)</i>",""],["t","<table><tr><td>NGÂN HÀNG NHÀ NƯỚC VIỆT NAM<b> NGÂN HÀNG NHÀ NƯỚC  CHI NHÁNH KHU VỰC…</b></td><td><b>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM  Độc lập - Tự do - Hạnh phúc</b></td></tr><tr><td>Số: /GP-…</td><td><i>…, ngày . .. tháng… năm…</i></td></tr></table>",""],["p","<b>GIẤY PHÉP</b>",""],["p","<b>THÀNH LẬP VÀ HOẠT ĐỘNG QUỸ TÍN DỤNG NHÂN DÂN</b>",""],["p","<b>GIÁM ĐỐC NGÂN HÀNG NHÀ NƯỚC CHI NHÁNH KHU VỰC ...</b>",""],["p","<i>Căn cứ Luật Ngân hàng Nhà nước Việt Nam ngày 16 tháng 6 năm 2010;</i>",""],["p","<i>Căn cứ Luật Các tổ chức tín dụng ngày 18 tháng 01 năm 2024;</i>",""],["p","<i>Căn cứ Nghị định số 2 6 /202 5 /NĐ-CP ngày 2 4 tháng 0 2 năm 202 5 của Chính phủ quy định chức năng, nhiệm vụ, quyền hạn và cơ cấu tổ chức của Ngân hàng Nhà nước Việt Nam;</i>",""],["p","<i>Căn cứ Nghị định số 162 /2024/NĐ-CP ngày 20 tháng 12 năm 2024 của Chính phủ quy định điều kiện cấp Giấy phép đối với quỹ tín dụng nhân dân, tổ chức tài chính vi mô và điều kiện đối với chủ sở hữu của tổ chức tín dụng là công ty trách nhiệm hữu hạn một thành viên, cổ đông sáng lập, thành viên sáng lập;</i>",""],["p","<i>Căn cứ Thông tư số .. ./202 5 /TT-NHNN ngày... tháng… năm 202 5 của Thống đốc Ngân hàng Nhà nước Việt Nam quy định về cấp Giấy phép lần đầu, cấp đổi Giấy phép của quỹ tín dụng nhân dân;</i>",""],["p","<i>Xét đơn đề nghị cấp Giấy phép thành lập và hoạt động của các thành viên sáng lập Quỹ tín dụng nhân dân... (tên quỹ tín dụng nhân dân) và hồ sơ kèm theo .</i>",""],["p","<b>QUYẾT ĐỊNH:</b>",""],["p","<b>Điều 1.</b> Cho phép thành lập quỹ tín dụng nhân dân như sau:",""],["p","1. Tên quỹ tín dụng nhân dân:","k"],["p","- Tên đầy đủ bằng tiếng Việt:","g"],["p","- Tên viết tắt bằng tiếng Việt (nếu có):","g"],["p","- Tên đầy đủ bằng tiếng Anh (nếu có):","g"],["p","- Tên viết tắt bằng tiếng Anh (nếu có):","g"],["p","- Tên giao dịch (nếu có):","g"],["p","2. Địa chỉ trụ sở chính:","k"],["p","<b>Điều 2.</b> Vốn điều lệ của Quỹ tín dụng nhân dân... (tên quỹ tín dụng nhân dân) là... đồng (bằng chữ:... ).",""],["p","<b>Điều 3.</b> Thời hạn hoạt động của Quỹ tín dụng nhân dân... (tên quỹ tín dụng nhân dân) là... năm.",""],["p","<b>Điều 4.</b> Địa bàn hoạt động:",""],["p","<b>Điều 5.</b> Nội dung hoạt động:",""],["p","<i>(Liệt kê các hoạt động được chấp thuận theo quy định tại Luật Các tổ chức tín dụng và quy định của Thống đốc Ngân hàng Nhà nước Việt Nam ).</i>",""],["p","<b>Điều 6.</b> Trong quá trình hoạt động, Quỹ tín dụng nhân dân... (tên quỹ tín dụng nhân dân) phải tuân thủ pháp luật Việt Nam.",""],["p","<b>Điều 7.</b> Giấy phép này có hiệu lực kể từ ngày ký.",""],["p","<b>Điều 8.</b> Giấy phép thành lập và hoạt động Quỹ tín dụng nhân dân... (tên quỹ tín dụng nhân dân) được lập thành 04 (bốn) bản chính: 01 (một) bản cấp cho Quỹ tín dụng nhân dân... (tên quỹ tín dụng nhân dân); 01 bản (một) gửi cơ quan đăng ký kinh doanh; 01 (một) bản lưu tại Ngân hàng Nhà nước chi nhánh Khu vực...; 01 (một) bản lưu tại hồ sơ cấp Giấy phép Quỹ tín dụng nhân dân... (tên quỹ tín dụng nhân dân)./.",""],["p","<b><i>Nơi nhận:</i></b>",""],["p","- Như Điều 8;","g"],["p","- UBND tỉnh, thành phố …","g"],["p","- UBND xã nơi QTDND được cấp Giấy phép hoạt động;","g"],["p","- Lưu: ...","g"],["p","<b>GIÁM ĐỐC</b>",""]]}],"phu_luc":true},{"id":"c6","title":"Phụ lục số 02 — Mẫu Đơn đề nghị cấp bản sao Giấy phép từ sổ gốc","articles":[{"id":"pl-6","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số 01 /202 5 /TT-NHNN ngày 29 / 4 / 2025 c ủa Th ố ng đốc Ngân hàng Nhà nước Việt Nam quy định về cấp Giấy phép lần đầu, cấp đổi Giấy phép của quỹ tín dụng nhân dân )</i>",""],["p","<b>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</b>",""],["p","<b>Độc lập - Tự do - Hạnh phúc</b>",""],["p","<b>ĐƠN ĐỀ NGHỊ CẤP BẢN SAO GIẤY PHÉP TỪ S Ổ GỐC</b>",""],["p","Kính gửi: Giám đốc Ngân hàng Nhà nước chi nhánh Khu vực…",""],["p","<b>1. Tên quỹ tín dụng nhân dân:</b>","k"],["p","- Tên đầy đủ bằng tiếng Việt:","g"],["p","- Tên viết tắt bằng tiếng Việt (nếu có):","g"],["p","- Tên đầy đủ bằng tiếng Anh (nếu có):","g"],["p","- Tên viết tắt bằng tiếng Anh (nếu có):","g"],["p","- Tên giao dịch (nếu có):","g"],["p","- Trụ sở chính tại:","g"],["p","- Địa chỉ thư điện tử:","g"],["p","Đề nghị Giám đốc Ngân hàng Nhà nước chi nhánh Khu vực... xem xét cấp bản sao từ sổ gốc đối với Giấy phép thành lập và hoạt động số... của Quỹ tín dụng nhân dân... được cấp ngày...",""],["p","<b>2. Lý do đề nghị :</b>","k"],["p","…………………………………………………………………………………….…………………………………………………………………………………….",""],["p","…………………………………………………………………………………….",""],["p","…………………………………………………………………………………….",""],["p","Quỹ tín dụng nhân dân………………….. cam kết chịu hoàn toàn trách nhiệm về sự trung thực và sự chính xác của Đơn đề nghị./.",""],["p","<i>..., ngày... tháng... năm...</i>",""],["p","<b>Người đại diện hợp pháp</b>",""],["p","<i>(Ký, ghi rõ họ tên, chức vụ và đóng dấu)</i>",""]]}],"phu_luc":true},{"id":"c7","title":"Phụ lục số 03 — Mẫu Đơn đề nghị cấp Giấy phép thành lập và hoạt động — quỹ tín dụng nhân dân","articles":[{"id":"pl-7","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số 01 /202 5 /TT-NHNN ngày 29 / 4 / 2025 của</i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam quy định về cấp Giấy phép lần đầu,</i>",""],["p","<i>cấp đổi Giấy phép của quỹ tín dụng nhân dân ) </i>",""],["p","<b>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc </b>",""],["p","<i>..., ngày... tháng... năm...</i>",""],["p","<b>ĐƠN ĐỀ NGHỊ CẤP GIẤY PHÉP THÀNH LẬP VÀ HOẠT ĐỘNG</b>",""],["p","<b> QUỸ TÍN DỤNG NHÂN DÂN</b>",""],["p","<b>Kính gửi:</b> Giám đốc Ngân hàng Nhà nước chi nhánh Khu vực...",""],["p","Căn cứ Luật Ngân hàng Nhà nước Việt Nam ngày 16 tháng 6 năm 2010;",""],["p","Căn cứ Luật Các tổ chức tín dụng ngày 18 tháng 01 năm 2024;",""],["p","Căn cứ Nghị định số 26/2025/NĐ-CP ngày 24 tháng 02 năm 2025 của Chính phủ quy định chức năng, nhiệm vụ, quyền hạn và cơ cấu tổ chức của Ngân hàng Nhà nước Việt Nam;",""],["p","Căn cứ Nghị định số 162/2024/NĐ-CP ngày 20 tháng 12 năm 2024 của Chính phủ quy định điều kiện cấp Giấy phép đối với quỹ tín dụng nhân dân, tổ chức tài chính vi mô và điều kiện đối với chủ sở hữu của tổ chức tín dụng là công ty trách nhiệm hữu hạn một thành viên, cổ đông sáng lập, thành viên sáng lập;",""],["p","Căn cứ Thông tư số .../2025/TT-NHNN ngày... tháng... năm 2025 của Thống đốc Ngân hàng Nhà nước Việt Nam quy định về cấp Giấy phép lần đầu, cấp đổi Giấy phép của quỹ tín dụng nhân dân;",""],["p","Căn cứ Biên bản Hội nghị thành lập Quỹ tín dụng nhân dân... (tên quỹ tín dụng nhân dân) ngày... tháng... năm...;",""],["p","Ban trù bị thành lập Quỹ tín dụng nhân dân... (tên quỹ tín dụng nhân dân) đề nghị Giám đốc Ngân hàng Nhà nước chi nhánh Khu vực... cấp Giấy phép thành lập và hoạt động quỹ tín dụng nhân dân với các nội dung sau đây:",""],["p","1. Tên quỹ tín dụng nhân dân:","k"],["p","- Tên đầy đủ bằng tiếng Việt:","g"],["p","- Tên viết tắt bằng tiếng Việt (nếu có):","g"],["p","- Tên đầy đủ bằng tiếng Anh (nếu có):","g"],["p","- Tên viết tắt bằng tiếng Anh (nếu có):","g"],["p","- Tên giao dịch (nếu có):","g"],["p","2. Địa điểm đặt trụ sở chính:","k"],["p","3. Địa bàn hoạt động:","k"],["p","4. Nội dung hoạt động:","k"],["p","5. Thời hạn hoạt động:","k"],["p","6. Vốn điều lệ: ... đồng (bằng chữ... ), trong đó tỷ lệ góp vốn của các thành viên sáng lập như sau:","k"],["t","<table><tr><td><b>STT</b></td><td><b>Tên tổ chức,</b><br><b>cá nhân</b></td><td><b>Địa chỉ</b></td><td><b>Số định danh cá nhân/Số Giấy phép thành lập hoặc số Giấy chứng nhận đăng ký doanh nghiệp hoặc văn bản tương đương</b></td><td><b>Giá trị vốn góp</b></td><td><b>Tỷ lệ vốn góp</b></td></tr><tr><td>1</td><td>Nguyễn Văn A</td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td>Công ty B</td><td></td><td></td><td></td><td></td></tr><tr><td>...</td><td></td><td></td><td></td><td></td><td></td></tr></table>",""],["p","7. Danh sách dự kiến những người được bầu, bổ nhiệm làm Chủ tịch và thành viên Hội đồng quản trị, Trưởng Ban và thành viên Ban kiểm soát, Giám đốc quỹ tín dụng nhân dân (nêu rõ họ, tên và các chức danh đề nghị chấp thuận của từng thành viên).","k"],["p","Chúng tôi xin cam kết:",""],["p","- Chịu trách nhiệm trước pháp luật về tính chính xác, trung thực của nội dung trong đơn, hồ sơ đề nghị cấp Giấy phép.","g"],["p","- Thực hiện đăng ký khai trương và công bố thông tin theo quy định của pháp luật.","g"],["p","- Chấp hành nghiêm chỉnh các quy định của pháp luật, của Ngân hàng Nhà nước và Điều lệ tổ chức và hoạt động quỹ tín dụng nhân dân./.","g"],["p","<b>TRƯỞNG BAN TRÙ BỊ</b>",""],["p","<i>(Ký, ghi rõ họ tên)</i>",""]]}],"phu_luc":true},{"id":"c8","title":"Phụ lục số 04 — Mẫu Sơ yếu lý lịch","articles":[{"id":"pl-8","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số 01 /202 5 /TT-NHNN ngày 29 / 4 /202 5 của Thống đốc Ngân hàng Nhà nước Việt Nam quy định về cấp Giấy phép lần đầu, cấp đổi Giấy phép của quỹ tín dụng nhân dân )</i>",""],["t","<table><tr><td></td><td><b>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc </b></td></tr><tr><td>Ảnh màu (4x6) đóng dấu giáp lai của cơ quan xác nhận lý lịch</td><td><b>SƠ YẾU LÝ LỊCH</b></td></tr></table>",""],["p","<b>1. Về bản thân:</b>","k"],["p","- Họ và tên:","g"],["p","- Ngày, tháng, năm sinh:","g"],["p","- Số định danh cá nhân:","g"],["p","- Tên, địa chỉ pháp nhân mà mình đại diện (trường hợp là người đại diện của pháp nhân):","g"],["p","<b>2. Trình độ học vấn:</b>","k"],["p","- Giáo dục phổ thông:","g"],["p","- Học hàm, học vị (nêu rõ tên, địa chỉ trường; chuyên ngành học; thời gian học; bằng cấp (liệt kê đầy đủ các bằng cấp)).","g"],["p","<b>3. Quá trình công tác:</b>","k"],["p","- Nghề nghiệp, đơn vị, chức vụ công tác từ năm 18 tuổi đến nay(1):","g"],["t","<table><tr><td><b>STT</b></td><td><b>Thời gian (từ tháng/năm đến tháng/năm)(2)</b></td><td><b>Đơn vị công tác</b></td><td><b>Chức vụ</b></td><td><b>Lĩnh vực hoạt động của doanh nghiệp và nhiệm vụ được giao</b></td><td><b>Ghi chú(3)</b></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></table>",""],["p","- Khen thưởng, kỷ luật, trách nhiệm theo kết luận thanh tra dẫn đến việc tổ chức tín dụng, chi nhánh ngân hàng nước ngoài bị xử phạt vi phạm hành chính(4).","g"],["p","<b>4. Năng lực hành vi dân sự(5) :</b>","k"],["p","<b>5. Cam kết trước pháp luật :</b>","k"],["p","Tôi cam kết:",""],["p","- Không vi phạm các quy định của pháp luật trong lĩnh vực tiền tệ và ngân hàng.","g"],["p","- Đáp ứng tiêu chuẩn, điều kiện để giữ chức danh... tại Quỹ tín dụng nhân dân... (tên quỹ tín dụng nhân dân) theo quy định tại Luật Các tổ chức tín dụng và các văn bản hướng dẫn có liên quan. Trong đó, tôi cam kết tuân thủ về việc có đạo đức nghề nghiệp theo quy định trong quá trình công tác tại các tổ chức tín dụng, chi nhánh ngân hàng nước ngoài (nếu có).","g"],["p","- Thông báo cho Quỹ tín dụng nhân dân... (tên quỹ tín dụng nhân dân) về bất kỳ thay đổi nào liên quan đến nội dung bản khai trên phát sinh trong thời gian Ngân hàng Nhà nước chi nhánh Khu vực... đang xem xét đề nghị của Quỹ tín dụng nhân dân... (tên quỹ tín dụng nhân dân).","g"],["p","- Các thông tin cá nhân tôi cung cấp cho Quỹ tín dụng nhân dân... (tên quỹ tín dụng nhân dân) là đúng sự thật. Tôi xin chịu hoàn toàn trách nhiệm đối với bất kỳ thông tin nào không đúng với sự thật tại bản khai này./.","g"],["p","<i>…, ngày… tháng… năm .. .</i> <b>Người khai</b> <i>(Ký, ghi rõ họ tên)(6)</i>",""],["p","<b>Ghi chú:</b>",""],["p","Người khai phải kê khai đầy đủ thông tin theo yêu cầu và chịu trách nhiệm trước pháp luật và quỹ tín dụng nhân dân về tính đầy đủ, chính xác, trung thực của hồ sơ, trường hợp không phát sinh thì ghi rõ không có.",""],["p","(1) Người khai phải kê khai đầy đủ công việc, đơn vị công tác, các chức vụ đã và đang nắm giữ.",""],["p","(2) Phải đảm bảo tính liên tục về mặt thời gian.",""],["p","(3) Ghi chú nếu đơn vị công tác thuộc các trường hợp sau:",""],["p","(i) Doanh nghiệp mà Nhà nước sở hữu từ 50% vốn điều lệ trở lên;",""],["p","(ii) Đơn vị theo quy định tại điểm e khoản 2 Điều 42 Luật Các tổ chức tín dụng;",""],["p","(iii) Đơn vị theo quy định tại điểm c và điểm d khoản 1 Điều 42 Luật Các tổ chức tín dụng.",""],["p","(4) Ghi cụ thể nếu nhân sự thuộc trường hợp nêu tại điểm d và điểm g khoản 1 Điều 42 Luật Các tổ chức tín dụng.",""],["p","(5) Ghi cụ thể: Đầy đủ/Hạn chế/Mất năng lực hành vi dân sự.",""],["p","(6) Chữ ký phải được chứng thực theo quy định của pháp luật.",""],["p","Ngoài những nội dung cơ bản trên, người khai có thể bổ sung các nội dung khác nếu thấy cần thiết.",""]]}],"phu_luc":true},{"id":"c9","title":"Phụ lục số 05 — Báo cáo khả năng tài chính tham gia góp vốn quỹ tín dụng nhân dân — đối với pháp nhân","articles":[{"id":"pl-9","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số 01 /202 5 /TT-NHNN ngày 29 / 4 / 2025 củ a</i>",""],["p","<i>Th ố ng đốc Ngân hàng Nhà nước Việt Nam quy định về cấp Giấy phép lần đầu,</i>",""],["p","<i>cấp đổi Giấy phép của quỹ tín dụng nhân dân )</i>",""],["p","<b>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc </b>",""],["p","<b>Kính gửi: Ban t rù bị thành lập Quỹ tín dụng nhân dân …</b>",""],["p","1. Thông tin về pháp nhân:","k"],["p","- Tên pháp nhân:","g"],["p","- Số Giấy phép thành lập hoặc số Giấy chứng nhận đăng ký doanh nghiệp hoặc văn bản tương đương, do… cấp ngày… tháng… năm…","g"],["p","- Vốn điều lệ:","g"],["p","- Địa chỉ trụ sở chính:","g"],["p","- Số điện thoại: Số Fax:","g"],["p","- Người đại diện theo pháp luật:","g"],["p","2. Khả năng về tài chính để góp vốn vào quỹ tín dụng nhân dân:","k"],["p","- A: Vốn chủ sở hữu (1).","g"],["p","- B: Tài sản dài hạn (2) trừ đi nợ dài hạn (3).","g"],["p","- C: Khả năng về tài chính để góp vốn vào Quỹ tín dụng nhân dân... (tên quỹ tín dụng nhân dân)","g"],["p","(C = A - B)",""],["p","Kết luận: Đủ khả năng tài chính góp vốn vào quỹ tín dụng nhân dân (chỉ kết luận này khi C tối thiểu bằng mức vốn cam kết góp của pháp nhân).",""],["p","<b>Ghi chú:</b>",""],["p","(1), (2), (3): Được lấy theo Báo cáo tài chính tại thời điểm gần nhất.",""],["p","<b>Người đại diện hợp pháp</b> <i>(Ký, ghi rõ họ tên, chức vụ và đóng dấu)</i>",""]]}],"phu_luc":true},{"id":"c10","title":"Phụ lục số 06 — Mẫu Văn bản cung cấp thông tin phục vụ đánh giá tiêu chuẩn, điều kiện — của nhân sự dự kiến","articles":[{"id":"pl-10","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số 01/202 5 /TT-NHNN ngày 29 / 4 / 2025 của Th ố ng đốc Ngân hàng Nhà nước Việt Nam quy định về cấp Giấy phép lần đầu,</i>",""],["p","<i>cấp đổi Giấy phép của quỹ tín dụng nhân dân )</i>",""],["p","<b>NGÂN HÀNG NHÀ NƯỚC</b>",""],["p","<b>VIỆT NAM</b>",""],["p","<b>NGÂN HÀNG NHÀ NƯỚC</b>",""],["p","<b>CHI NHÁNH KHU VỰC…</b>",""],["p","<b>Số:…</b>",""],["p","<b>V/v cung cấp thông tin phục vụ đánh giá tiêu chuẩn của nhân sự dự kiến</b>",""],["p","<b>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</b>",""],["p","<b>Độc lập - Tự do - Hạnh phúc</b>",""],["p","<i>…, ngày… tháng… năm…</i>",""],["p","Kính gửi: Ngân hàng Nhà nước chi nhánh Khu vực...",""],["p","Liên quan đến Công văn số… ngày… của Ngân hàng Nhà nước chi nhánh Khu vực… về việc…, Ngân hàng Nhà nước chi nhánh Khu vực… cung cấp thông tin qua công tác thanh tra, giám sát như sau:",""],["p","<b>I. <b>Thông tin có liên quan đến việc chấp hành các quy định pháp luật về tiêu chuẩn, điều kiện đối với nhân sự dự kiến</b></b>",""],["p","1. Nhân sự dự kiến thứ nhất","k"],["p","☐ Là người phải chịu trách nhiệm theo kết luận kiểm tra dẫn đến việc tổ chức tín dụng, chi nhánh ngân hàng nước ngoài bị xử phạt vi phạm hành chính trong lĩnh vực tiền tệ và ngân hàng ở khung phạt tiền cao nhất đối với hành vi vi phạm quy định về giấy phép, quản trị, điều hành, cổ phần, cổ phiếu, góp vốn, mua cổ phần, cấp tín dụng, mua trái phiếu doanh nghiệp, tỷ lệ bảo đảm an toàn theo quy định pháp luật về xử lý vi phạm hành chính trong lĩnh vực tiền tệ và ngân hàng.",""],["p","☐ Là người có tên tại kết luận thanh tra, kiểm tra có trách nhiệm dẫn đến việc tổ chức tín dụng, chi nhánh ngân hàng nước ngoài bị xử phạt vi phạm hành chính trong lĩnh vực tiền tệ và ngân hàng mà quyết định xử phạt vi phạm hành chính đó chưa được chấp hành xong.",""],["p","☐ Là người bị xử phạt vi phạm hành chính đối với các hành vi vi phạm hành chính trong lĩnh vực tiền tệ và ngân hàng trong thời hạn 06 tháng kể từ ngày ký quyết định xử phạt cảnh cáo hoặc 01 năm kể từ ngày chấp hành xong quyết định xử phạt vi phạm hành chính khác hoặc 01 năm kể từ ngày hết thời hiệu thi hành quyết định xử phạt vi phạm hành chính.",""],["p","☐ Là người phải chịu trách nhiệm cá nhân đối với các vi phạm về giấy phép, quản trị, điều hành, cổ phần, cổ phiếu, góp vốn, mua cổ phần, cấp tín dụng, mua trái phiếu doanh nghiệp, tỷ lệ bảo đảm an toàn, phân loại tài sản có, cam kết ngoại bảng, trích lập và sử dụng dự phòng để xử lý rủi ro theo quy định của pháp luật nêu tại kết luận thanh tra, kiểm tra, kiểm toán mà kiến nghị liên quan đến các vi phạm đó chưa được khắc phục, chỉnh sửa.",""],["p","Trường hợp nhân sự dự kiến thuộc một trong các trường hợp nêu trên, cung cấp thông tin chi tiết, trong đó tối thiểu bao gồm các nội dung như sau:",""],["p","- Trách nhiệm cá nhân (nếu có) của nhân sự dự kiến dẫn đến tổ chức tín dụng/chi nhánh tổ chức tín dụng/chi nhánh ngân hàng nước ngoài bị xử phạt vi phạm hành chính <i>(nêu rõ nếu xử phạt ở khung phạt tiền cao nhất);</i>","g"],["p","- Quyết định xử phạt vi phạm hành chính đối với nhân sự dự kiến (nếu có).","g"],["p","1.2. Thông tin khác về việc tuân thủ quy định pháp luật liên quan đến tiêu chuẩn, điều kiện đối với nhân sự dự kiến (nếu có).",""],["p","<i>(Trường hợp phát sinh xử phạt vi phạm hành chính, cung cấp các quyết định xử phạt vi phạm hành chính, biên bản xử phạt và các tài liệu liên quan).</i>",""],["p","2. Nhân sự dự kiến thứ hai:...","k"],["p","…",""],["p","<b>II. Thông tin cụ thể theo đề nghị của đơn vị đầu mối (nếu có)</b>",""],["p","<b>III. Ý kiến đánh giá về việc tuân thủ tiêu chuẩn, điều kiện đối với nhân sự dự kiến</b>",""],["p","1. Tên nhân sự thứ nhất: Tuân thủ/Không tuân thủ tiêu chuẩn, điều kiện đối với nhân sự dự kiến trên cơ sở thông tin đã cung cấp tại Phần I Văn bản này.","k"],["p","Trường hợp không tuân thủ, nêu rõ lý do.",""],["p","2. Tên nhân sự thứ hai: Tuân thủ/Không tuân thủ tiêu chuẩn, điều kiện đối với nhân sự dự kiến trên cơ sở thông tin đã cung cấp tại Phần I Văn bản này.","k"],["p","Trường hợp không tuân thủ, nêu rõ lý do.",""],["p","…",""],["p","Trên đây là thông tin, ý kiến đánh giá của Ngân hàng Nhà nước chi nhánh Khu vực… đối với nhân sự dự kiến… gửi Ngân hàng Nhà nước chi nhánh Khu vực… ./.",""],["p","<b><i>Nơi nhận:</i></b>",""],["p","<b>- Như trên;</b>","g"],["p","<b>- Lưu: … </b>","g"],["p","<b>GIÁM ĐỐC</b>",""],["p","<i>(Ký tên và đóng dấu)</i>",""]]}],"phu_luc":true},{"id":"c11","title":"Phụ lục số 07 — Mẫu Giấy phép cấp đổi Giấy phép thành lập và hoạt động — quỹ tín dụng nhân dân","articles":[{"id":"pl-11","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số 01 /202 5 /TT-NHNN ngày 29 / 4 / 2025 của</i>",""],["p","<i>Th ố ng đốc Ngân hàng Nhà nước Việt Nam quy định về cấp Giấy phép lần đầu,</i>",""],["p","<i>cấp đổi Giấy phép của quỹ tín dụng nhân dân )</i>",""],["t","<table><tr><td>NGÂN HÀNG NHÀ NƯỚC VIỆT NAM<b> NGÂN HÀNG NHÀ NƯỚC  CHI NHÁNH KHU VỰC.. . </b></td><td><b>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM  Độc lập - Tự do - Hạnh phúc</b></td></tr><tr><td>Số: /GP-…</td><td><i>…, ngày… tháng… năm…</i></td></tr></table>",""],["p","<b>GIẤY PHÉP</b>",""],["p","<b>THÀNH LẬP VÀ HOẠT ĐỘNG QUỸ TÍN DỤNG NHÂN DÂN</b>",""],["p","<b>GIÁM ĐỐC NGÂN HÀNG NHÀ NƯỚC CHI NHÁNH KHU VỰC…</b>",""],["p","<i>Căn cứ Luật Ngân hàng Nhà nước Việt Nam ngày 16 tháng 6 năm 2010;</i>",""],["p","<i>Căn cứ Luật Các tổ chức tín dụng ngày 18 tháng 01 năm 2024;</i>",""],["p","<i>Căn cứ Nghị định số 2 6 /202 5 /NĐ-CP ngày 2 4 tháng 0 2 năm 202 5 của Chính phủ quy định chức năng, nhiệm vụ, quyền hạn và cơ cấu tổ chức của Ngân hàng Nhà nước Việt Nam;</i>",""],["p","<i>Căn cứ Thông tư số .. ./202 5 /TT-NHNN ngày... tháng .. . năm 202 5 của Thống đốc Ngân hàng Nhà nước Việt Nam quy định về cấp Giấy phép lần đầu, cấp đổi Giấy phép của quỹ tín dụng nhân dân;</i>",""],["p","<i>Xét đơn đề nghị cấp đổi Giấy phép thành lập và hoạt động của Quỹ tín dụng nhân dân … (tên quỹ tín dụng nhân dân) và hồ sơ kèm theo;</i>",""],["p","<b>QUYẾT ĐỊNH:</b>",""],["p","<b>Điều 1.</b> Cấp đổi Giấy phép thành lập và hoạt động số … ngày … cho Quỹ tín dụng nhân dân … (tên quỹ tín dụng nhân dân) như sau:",""],["p","1. Tên quỹ tín dụng nhân dân:","k"],["p","- Tên đầy đủ bằng tiếng Việt: Tên viết tắt bằng tiếng việt (nếu có):","g"],["p","- Tên bằng tiếng Anh (nếu có): Tên viết tắt bằng tiếng Anh (nếu có):","g"],["p","- Tên giao dịch (nếu có):","g"],["p","2. Địa chỉ trụ sở chính:","k"],["p","<b>Điều 2.</b> Vốn điều lệ của Quỹ tín dụng nhân dân… (tên quỹ tín dụng nhân dân) là... đồng (bằng chữ…).",""],["p","<b>Điều 3.</b> Thời hạn hoạt động của Quỹ tín dụng nhân dân… (tên quỹ tín dụng nhân dân) là… năm (là thời hạn hoạt động được quy định tại Giấy phép do Ngân hàng Nhà nước chi nhánh tỉnh, thành phố cấp trước đây) kể từ ngày… (là ngày hiệu lực của Giấy phép được Ngân hàng Nhà nước chi nhánh tỉnh, thành phố cấp trước đây).",""],["p","Thời hạn hoạt động của Quỹ tín dụng nhân dân… (tên quỹ tín dụng nhân dân) là 50 năm (trường hợp Giấy phép do Ngân hàng Nhà nước chi nhánh tỉnh, thành phố cấp trước đây không quy định thời hạn hoạt động) kể từ ngày… (là ngày hiệu lực của Giấy phép được Ngân hàng Nhà nước chi nhánh tỉnh, thành phố cấp trước đây).",""],["p","<b>Điều 4.</b> Địa bàn hoạt động:",""],["p","<b>Điều 5.</b> Nội dung hoạt động:",""],["p","<i>(Liệt kê các hoạt động được chấp thuận theo quy định tại Luật Các tổ chức tín dụng và quy định của Thống đốc Ngân hàng Nhà nước Việt Nam ).</i>",""],["p","<b>Điều 6.</b> Trong quá trình hoạt động, Quỹ tín dụng nhân dân… (tên quỹ tín dụng nhân dân) phải tuân thủ pháp luật Việt Nam.",""],["p","<b>Điều 7 .</b> Giấy phép này có hiệu lực kể từ ngày ký và thay thế Giấy phép thành lập và hoạt động số… ngày… và các văn bản sửa đổi, bổ sung Giấy phép có liên quan.",""],["p","<b>Điều 8.</b> Giấy phép cấp đổi cho Quỹ tín dụng nhân dân… (tên quỹ tín dụng nhân dân) được lập thành 04 (bốn) bản chính: 01 (một) bản cấp cho Quỹ tín dụng nhân dân... (tên quỹ tín dụng nhân dân); 01 (một) bản gửi cơ quan đăng ký kinh doanh; 01 (một) bản lưu tại Ngân hàng Nhà nước chi nhánh Khu vực...; 01 (một) bản lưu tại hồ sơ cấp Giấy phép Quỹ tín dụng nhân dân… (tên quỹ tín dụng nhân dân)./.",""],["p","<b><i>Nơi nhận:</i></b>",""],["p","- Như Điều 8;","g"],["p","- UBND tỉnh, thành phố …;","g"],["p","- UBND xã nơi QTDND được cấp Giấy phép hoạt động;","g"],["p","- Lưu: ...","g"],["p","<b>GIÁM ĐỐC</b>",""]]}],"phu_luc":true},{"id":"c12","title":"Phụ lục số 08 — Mẫu Đơn đề nghị cấp đổi Giấy phép quỹ tín dụng nhân dân","articles":[{"id":"pl-12","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số 01 /202 5 /TT-NHNN ngày 29 / 4 / 2025 của</i>",""],["p","<i>Th ố ng đốc Ngân hàng Nhà nước Việt Nam quy định về cấp Giấy phép lần đầu,</i>",""],["p","<i>cấp đổi Giấy phép của quỹ tín dụng nhân dân )</i>",""],["p","<b>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</b>",""],["p","<b>Độc lập - Tự do - Hạnh phúc</b>",""],["p","<b>ĐƠN ĐỀ NGHỊ CẤP ĐỔI GIẤY PHÉP</b>",""],["p","Kính gửi: Giám đốc Ngân hàng Nhà nước chi nhánh Khu vực…",""],["p","<b>1. Tên quỹ tín dụng nhân dân:</b>","k"],["p","- Tên đầy đủ bằng tiếng Việt:","g"],["p","- Tên viết tắt bằng tiếng Việt (nếu có):","g"],["p","- Tên đầy đủ bằng tiếng Anh (nếu có):","g"],["p","- Tên viết tắt bằng tiếng Anh (nếu có):","g"],["p","- Trụ sở chính tại:","g"],["p","- Địa chỉ thư điện tử:","g"],["p","Đề nghị Giám đốc Ngân hàng Nhà nước chi nhánh Khu vực… xem xét:",""],["p","- Cấp đổi Giấy phép thành lập và hoạt động quỹ tín dụng nhân dân với các nội dung hoạt động sau đây:","g"],["p","<i>(Liệt kê các hoạt động mà quỹ tín dụng nhân dân đề nghị ghi nhận trong Giấy phép cấp đổi, bao gồm các nội dung hoạt động đã được ghi trong Giấy phép hiện hành và các văn bản sửa đổi, bổ sung Giấy phép có liên quan. Các nội dung hoạt động đề nghị phải phù hợp với quy định của Luật Các tổ chức tín dụng và các quy định của Thống đốc Ngân hàng Nhà nước Việt Nam )</i>",""],["p","- Bổ sung nội dung hoạt động đồng thời cấp đổi Giấy phép thành lập và hoạt động quỹ tín dụng nhân dân với các nội dung hoạt động sau đây:","g"],["p","<i>(Liệt kê các hoạt động mà quỹ tín dụng nhân dân đề nghị ghi nhận trong Giấy phép cấp đổi, bao gồm: (i) các nội dung hoạt động đã được ghi trong Giấy phép hiện hành và các văn bản sửa đổi, bổ sung Giấy phép có liên quan. Các nội dung hoạt động đề nghị phải phù hợp với quy định của Luật Các tổ chức tín dụng và các quy định của Thống đốc Ngân hàng Nhà nước Việt Nam; (ii) các nội dung hoạt động đề nghị bổ sung . Các nội dung hoạt động đề nghị bổ sung phải phù hợp với quy định của Luật Các tổ chức tín dụng và các quy định của Thống đốc Ngân hàng Nhà nước Việt Nam).</i>",""],["p","<b>2. Lý do và sự cần thiết cấp đổi Giấy phép/bổ sung nội dung hoạt động đồng thời cấp đổi Giấy phép:</b>","k"],["p","……………………………………………………………………………………….……………………………………………………………………………………….",""],["p","……………………………………………………………………………………….",""],["p","……………………………………………………………………………………….",""],["p","Quỹ tín dụng nhân dân… cam kết:",""],["p","a) Chịu trách nhiệm hoàn toàn về sự trung thực và sự chính xác của Đơn đề nghị và hồ sơ kèm theo.","d"],["p","b) Cam kết đảm bảo đáp ứng các điều kiện để thực hiện các nội dung hoạt động theo đề nghị và tiếp tục duy trì việc đáp ứng các điều kiện này theo quy định./.","d"],["p","<i>..., ngày... tháng... năm...</i>",""],["p","<b>Người đại diện hợp pháp</b>",""],["p","<i>(Ký, ghi rõ họ tên, chức vụ và đóng dấu)</i>",""]]}],"phu_luc":true}],"chu_thich":{},"tom_tat":[["p","<b>Thông tư số 01/2025/TT-NHNN</b> ngày 29/04/2025 của Thống đốc Ngân hàng Nhà nước Việt Nam quy định về cấp Giấy phép lần đầu, cấp đổi Giấy phép của Quỹ tín dụng nhân dân (QTDND).",""],["p","<b>ĐÁNH GIÁ CHIẾN LƯỢC TỪ CHUYÊN GIA:</b> Thông tư 01/2025/TT-NHNN phản ánh tư duy quản lý \"Phòng bệnh hơn chữa bệnh\" của NHNN đối với khối QTDND. Bằng việc phân quyền mạnh mẽ cho <b>NHNN chi nhánh Khu vực</b> (được quyền kiểm tra thực địa và đình chỉ khai trương) và lượng hóa khái niệm \"Đạo đức nghề nghiệp\" của dàn nhân sự cấp cao thông qua lý lịch tư pháp và lịch sử thanh tra, Thông tư này tạo ra một \"màng lọc rủi ro\" nhiều lớp, đảm bảo chỉ những tổ chức có năng lực tài chính thật và những nhân sự trong sạch mới được phép huy động tiền gửi của nhân dân.",""],["h","Bảng 1. Tóm tắt tổng quan văn bản",""],["t","<table><tr><td><b>Nội dung</b></td><td><b>Phân tích chi tiết</b></td></tr><tr><td><b>Tên văn bản</b></td><td>Thông tư số 01/2025/TT-NHNN quy định về cấp Giấy phép lần đầu, cấp đổi Giấy phép của quỹ tín dụng nhân dân.</td></tr><tr><td><b>Cơ quan ban hành</b></td><td>Ngân hàng Nhà nước Việt Nam (Thống đốc ký ban hành ngày 29/04/2025, hiệu lực từ 15/06/2025).</td></tr><tr><td><b>Mục tiêu ban hành</b></td><td>Thể chế hóa các quy định của Luật Các tổ chức tín dụng 2024 và Nghị định 162/2024/NĐ-CP. Nhằm thắt chặt các \"van an toàn\" ngay từ khâu gia nhập thị trường đối với loại hình QTDND (kiểm soát chặt nhân sự, nguồn vốn, cơ sở vật chất), ngăn chặn từ xa rủi ro sở hữu chéo và yếu kém trong quản trị điều hành.</td></tr><tr><td><b>Phạm vi điều chỉnh</b></td><td>Điều chỉnh trình tự, thủ tục và hồ sơ pháp lý đối với 03 nhóm nghiệp vụ: (1) Cấp Giấy phép thành lập và hoạt động lần đầu cho QTDND.(2) Cấp đổi Giấy phép đang hoạt động.(3) Cấp bản sao Giấy phép từ sổ gốc,.</td></tr><tr><td><b>Đối tượng áp dụng</b></td><td>- Quỹ tín dụng nhân dân, Ban trù bị thành lập QTDND.- Ngân hàng Nhà nước chi nhánh Khu vực (NHNN Khu vực).- Các tổ chức, cá nhân có liên quan đến việc thành lập, cấp phép QTDND.</td></tr><tr><td><b>Nội dung quản lý chính</b></td><td>Thiết lập bộ tiêu chuẩn khắt khe về <b>hồ sơ đầu vào</b>: Yêu cầu minh bạch tài chính của thành viên góp vốn; bắt buộc phải có Dự thảo Hệ thống kiểm soát, kiểm toán nội bộ; yêu cầu đánh giá nghiêm ngặt \"đạo đức nghề nghiệp\" và lịch sử tuân thủ pháp luật của nhân sự dự kiến cấp cao (HĐQT, Ban Điều hành, BKS),.</td></tr></table>",""],["h","Bảng 2. Nghĩa vụ của các đối tượng chịu sự điều chỉnh",""],["t","<table><tr><td><b>Nhóm đối tượng</b></td><td><b>Nghĩa vụ/Nhiệm vụ pháp lý</b></td><td><b>Hành động cụ thể cần thực hiện để tuân thủ</b></td></tr><tr><td><b>Ban trù bị thành lập QTDND</b></td><td><b>Nghĩa vụ tổ chức, chuẩn bị minh bạch hồ sơ pháp lý và vốn.</b></td><td>- Tổ chức cuộc họp Đại hội thành viên đầu tiên đúng quy định.- Hướng dẫn và thông báo cho các thành viên sáng lập gửi tiền góp vốn vào tài khoản phong tỏa do Ban trù bị mở tại một NHTM.- Chịu trách nhiệm tuyệt đối về tính đầy đủ, chính xác của hồ sơ trình NHNN. Thông báo lý do cho thành viên nếu bị từ chối cấp phép.</td></tr><tr><td><b>Quỹ tín dụng nhân dân (QTDND)</b></td><td><b>Nghĩa vụ thiết lập hệ thống phòng vệ rủi ro và an toàn cơ sở vật chất.</b></td><td>- Phải xây dựng <b>Phương án kinh doanh dự kiến 3 năm đầu</b> có tính khả thi.- Xây dựng Dự thảo quy định nội bộ về tổ chức, hoạt động, kiểm soát và kiểm toán nội bộ bám sát Điều 101 Luật Các TCTD.- Đảm bảo trụ sở thuộc quyền sở hữu/sử dụng hợp pháp, có kho tiền đạt chuẩn kỹ thuật an toàn kho quỹ của NHNN trước khi khai trương,.</td></tr><tr><td><b>Nhân sự cấp cao dự kiến</b> <i>(HĐQT, Ban kiểm soát, Giám đốc)</i></td><td><b>Nghĩa vụ chứng minh năng lực hành vi, năng lực chuyên môn và đạo đức nghề nghiệp.</b></td><td>- Nộp Sơ yếu lý lịch, Phiếu lý lịch tư pháp đầy đủ thông tin án tích và cấm đảm nhiệm chức vụ.- Kê khai trung thực quá trình công tác, đặc biệt là thông tin về việc <i>có hay không bị xử phạt vi phạm hành chính</i> lĩnh vực ngân hàng, hoặc liên quan đến kết luận thanh tra,,.</td></tr></table>",""],["h","Bảng 3. Quyền hạn và trách nhiệm của cơ quan quản lý",""],["t","<table><tr><td><b>Cơ quan quản lý</b></td><td><b>Quyền hạn thẩm định, giám sát</b></td><td><b>Nghĩa vụ/Trách nhiệm tổ chức thực hiện</b></td></tr><tr><td><b>Ngân hàng Nhà nước chi nhánh Khu vực</b></td><td>- Thẩm quyền tối cao tại địa bàn trong việc <b>Chấp thuận nguyên tắc</b>, <b>Cấp/Từ chối cấp</b> Giấy phép và Cấp đổi Giấy phép cho QTDND.- Quyền <b>Đình chỉ khai trương hoạt động</b> nếu kiểm tra thực tế thấy QTDND không đáp ứng điều kiện (đặc biệt về kho quỹ, CNTT, nhân sự).</td><td>- Tiếp nhận, thẩm định tính đầy đủ, hợp lệ của hồ sơ; Trả lời bằng văn bản yêu cầu bổ sung hoặc xác nhận hồ sơ.- Kiểm tra thực địa, chỉ đạo, giám sát QTDND hoàn thiện các điều kiện vật chất trước ngày khai trương.- Quản lý, lưu trữ hồ sơ cấp phép gốc của QTDND trên địa bàn.</td></tr><tr><td><b>Cục An toàn hệ thống các TCTD (NHNN)</b></td><td>Là cơ quan tham mưu hoạch định chính sách quản lý an toàn.</td><td>- Phối hợp đôn đốc, hướng dẫn NHNN Khu vực giải quyết các vướng mắc trong quá trình áp dụng tiêu chuẩn cấp phép mới.</td></tr></table>",""],["h","Bảng 4. Chế tài xử lý vi phạm",""],["p","<i>(Lưu ý chuyên môn: Thông tư 01/2025/TT-NHNN xác lập các \"Hệ quả pháp lý/Chế tài hành chính trực tiếp\" trong khâu cấp phép. Các hình thức phạt tiền cụ thể sẽ được đối chiếu áp dụng theo Nghị định 340/2025/NĐ-CP về xử phạt vi phạm hành chính lĩnh vực tiền tệ, ngân hàng có hiệu lực cùng kỳ).</i>",""],["t","<table><tr><td><b>Hành vi vi phạm</b></td><td><b>Đối tượng áp dụng</b></td><td><b>Hình thức xử lý &amp; Biện pháp khắc phục</b></td><td><b>Ghi chú (Căn cứ pháp lý)</b></td></tr><tr><td><b>Không đáp ứng đủ điều kiện thực tế để khai trương hoạt động</b> (Ví dụ: Kho tiền không đạt chuẩn an toàn, hệ thống CNTT chưa sẵn sàng).</td><td>Quỹ tín dụng nhân dân (đã được cấp phép nhưng chưa khai trương)</td><td><b>Chế tài hành chính trực tiếp:</b> Giám đốc NHNN Khu vực ra quyết định <b>Đình chỉ khai trương hoạt động</b> cho đến khi khắc phục xong.</td><td><i>Biện pháp ngăn chặn rủi ro vận hành (Operational Risk) theo khoản 5 Điều 18 TT 01/2025.</i></td></tr><tr><td><b>Gian lận, giả mạo giấy tờ chứng minh đủ điều kiện cấp phép</b> trong hồ sơ đề nghị.</td><td>Ban trù bị, Cá nhân kê khai hồ sơ, QTDND</td><td><b>Về thủ tục:</b> NHNN từ chối cấp Giấy phép.<b>Về chế tài:</b> Phạt tiền từ <b>150 - 200 triệu đồng</b>. Thu hồi Giấy phép (nếu đã cấp).</td><td><i>Dẫn chiếu khoản 5, khoản 8 Điều 7 Nghị định 340/2025/NĐ-CP.</i></td></tr><tr><td><b>Nhân sự dự kiến che giấu lịch sử vi phạm hành chính</b>, hoặc đang là đối tượng chịu trách nhiệm tại Kết luận thanh tra chưa khắc phục xong.</td><td>Cá nhân dự kiến bầu (HĐQT, BKS, Giám đốc)</td><td><b>Bộ lọc nhân sự:</b> Bị NHNN chi nhánh Khu vực đánh giá là <b>không đủ tiêu chuẩn, điều kiện (không có đạo đức nghề nghiệp)</b> và kiên quyết loại khỏi danh sách nhân sự được duyệt,,.</td><td><i>Dựa trên cơ chế kiểm tra chéo (Cross-check) tại Phụ lục 06 của Thông tư 01/2025.</i></td></tr></table>",""]]};
